            if index + 1 >= len(argv):
                raise ValueError("--color requires a mode")
            mode = argv[index + 1]
            if mode not in {"auto", "always", "never"}:
                raise ValueError(f"invalid color mode: {mode}")
            if selected is not None and selected != mode:
                raise ValueError("conflicting color modes")
            selected = mode
            index += 2
            continue

        if argument == "--no-color":
            if selected is not None and selected != "never":
                raise ValueError("conflicting color modes")
            selected = "never"

        index += 1

    return selected if selected is not None else "auto"
