from __future__ import annotations

from collections.abc import Sequence


def parse_color_mode(argv: Sequence[str]) -> str:
    """Return the requested color mode, defaulting to ``auto``."""
    mode = "auto"
    explicit_mode: str | None = None
    index = 0

    while index < len(argv):
        argument = argv[index]

        if argument == "--no-color":
            requested = "never"
        elif argument == "--color":
            index += 1
            if index >= len(argv):
                raise ValueError("--color requires a mode")
            requested = argv[index]
            if requested not in {"auto", "always", "never"}:
                raise ValueError(f"invalid color mode: {requested}")
        else:
            index += 1
            continue

        if explicit_mode is not None and explicit_mode != requested:
            raise ValueError("conflicting color modes")
        explicit_mode = requested
        mode = requested
        index += 1

    return mode
